(()=>{"use strict";const d=document,S=5,k="module8-progress-v2",q=s=>d.querySelector(s),all=s=>[...d.querySelectorAll(s)],bar=q("#progressBar"),counter=q("#sessionCounter"),status=q("#appStatus"),es=d.documentElement.lang==="es";let done=new Set;const say=m=>{if(status)status.textContent=m},store={get(){try{const v=JSON.parse(localStorage.getItem(k)||"[]");return Array.isArray(v)?v:[]}catch(e){console.warn("Progress read failed",e);say(es?"No se pudo leer el progreso guardado.":"Impossible de lire la progression enregistrée.");return[]}},set(v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch(e){console.warn("Progress save failed",e);say(es?"El progreso no pudo guardarse.":"La progression n’a pas pu être enregistrée.");return false}}};function render(){const n=done.size,p=Math.round(n/S*100);if(bar){bar.style.width=p+"%";bar.textContent=p+"%";bar.setAttribute("aria-valuenow",p)}if(counter)counter.textContent=es?`${n} / ${S} sesiones terminadas`:`${n} / ${S} séances terminées`;all(".btn-complete").forEach(b=>{const on=done.has(+b.dataset.session);b.classList.toggle("is-complete",on);b.setAttribute("aria-pressed",on);b.textContent=on?(es?"✓ Sesión terminada":"✓ Séance terminée"):(es?`✓ Marcar la sesión ${b.dataset.session} como terminada`:`✓ Marquer la séance ${b.dataset.session} comme terminée`)})}done=new Set(store.get().filter(n=>Number.isInteger(n)&&n>=1&&n<=S));render();d.addEventListener("click",e=>{const b=e.target.closest("button[data-session],button[data-action=reset]");if(!b)return;if(b.dataset.action==="reset"){done.clear();store.set([]);render();say(es?"Progreso reiniciado.":"Progression réinitialisée.");return}const n=+b.dataset.session;done.has(n)?done.delete(n):done.add(n);store.set([...done].sort());render();say(es?"Progreso actualizado.":"Progression mise à jour.")});addEventListener("error",e=>{console.error("Module 8 error",e.error||e.message);say(es?"Se produjo un error inesperado.":"Une erreur inattendue est survenue.")});addEventListener("unhandledrejection",e=>{console.error("Module 8 rejection",e.reason);say(es?"No se pudo completar una operación.":"Une opération n’a pas pu aboutir.")});if("serviceWorker"in navigator&&location.protocol.startsWith("http"))addEventListener("load",()=>navigator.serviceWorker.register("module8-sw.js").catch(e=>console.warn("Cache unavailable",e)))})();
